// <CodeListing>'s line numbers in the real app: every line's code starts at the same x, so a two-digit number does not push
// its line right (the number column used to lose its padding to box-sizing: border-box from line 10 on). Checked on the
// Module 1 Stepper (lesson 1.4, the add-frames program: 14 lines, generated by tools/trace).
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { expect, test } from '@playwright/test';
import type { TraceFile } from '../src/content-model/types';
import { availableModules, codeStartXs, reachCard, ROOT } from './lib';

const mod = availableModules().find(m => m.id === 'm01')!;
const lesson = mod.lessons.find(l => l.stem === '04-functions-and-scope')!;
const add = JSON.parse(readFileSync(path.join(ROOT, 'src/generated/traces/add-frames.json'), 'utf8')) as TraceFile;

test('the Module 1 Stepper lines up the code of lines 9 and 10 (and every other line)', async ({ page }) => {
  test.setTimeout(180_000);
  const lines = add.source.replace(/\n$/, '').split('\n').length;
  expect(lines, 'add-frames has 10 or more lines').toBeGreaterThanOrEqual(10);
  const at = new Date().toISOString();
  const doc = { version: 1, seed: '00e2e00e2e00e2e0', createdAt: at, settings: {}, cards: {}, lessons: {}, samples: {}, exercises: {}, quizzes: { [`${mod.id}:retrieval`]: { score: 1, total: 1, passed: true, at, answers: {} } }, projects: {}, streak: { days: [], longest: 0 } };
  await page.context().addInitScript(j => { try { if (!localStorage.getItem('tdcc:v1:progress')) localStorage.setItem('tdcc:v1:progress', j); } catch { /* no storage */ } }, JSON.stringify(doc));
  const card = await reachCard(page, mod, lesson.stem, '[data-interaction="stepper"][data-sample="add-frames"]');
  const listing = card.locator('[data-interaction="stepper"] ol[aria-label="Program"]');
  await expect(listing.locator(':scope > li')).toHaveCount(lines);
  const xs = await codeStartXs(listing);
  test.info().annotations.push({ type: 'code x', description: `line 9: ${xs[8]}, line 10: ${xs[9]}, all: ${xs.join(', ')}` });
  console.log(`code x: line 9 = ${xs[8]}, line 10 = ${xs[9]}; all lines: ${xs.join(', ')}`);
  expect(xs[9], 'line 10 code starts where line 9 code starts').toBe(xs[8]);
  expect(new Set(xs).size, 'every line starts at one x').toBe(1);
});
